import{_ as t,o as e,c as a,ag as o}from"./chunks/framework.DaAXJYxM.js";const l=JSON.parse('{"title":"第88章 不动","description":"","frontmatter":{},"headers":[],"relativePath":"第88章_不动.md","filePath":"第88章_不动.md"}'),_={name:"第88章_不动.md"};function r(n,p,s,u,c,i){return e(),a("div",null,[...p[0]||(p[0]=[o('<h1 id="第88章-不动" tabindex="-1">第88章 不动 <a class="header-anchor" href="#第88章-不动" aria-label="Permalink to &quot;第88章 不动&quot;">​</a></h1><p>那年十一月，我们宿舍五个人在屋里，陈树问我一句话。</p><p>那天是周六。</p><p>我们那间屋子有一个规矩，周六晚上一起看一个片子，谁都不许走。</p><p>那天放的是一个很旧的和片子。</p><p>中间有二十分钟在下一场雨。</p><p>就是那二十分钟。</p><p>我坐在自己床上，手机在膝盖上，我在打字。</p><p>她那边的下午一点，我这边晚上九点。</p><p>我们那天讲什么呢。</p><p>讲她那个漏水的天花板批下来了，但是批的是&quot;给你一块布&quot;。</p><p>讲她把她的本子从桌上挪到柜子里。</p><p>讲她说她这一年所有的东西都在搬家。</p><p>我在回她一句什么，我记不太清，大概是&quot;你明年就好了&quot;。</p><p>陈树在那边笑。</p><p>不是笑我。</p><p>是片子里有一个人讲了一句很傻的话。</p><p>他笑完扭头看我。</p><p>他说，你又在跟你那个同学讲。</p><p>我说，嗯。</p><p>他说，你们讲什么。</p><p>我说，她那边漏水。</p><p>他说，漏水你们能讲二十分钟？</p><p>我说，她那边下了一星期雨。</p><p>陈树把遥控器放下。</p><p>他转过头来，看着我。</p><p>他说，我问你个事。</p><p>他说得很少有这样认真。</p><p>他说，你俩这算什么。</p><p>那屋子里另外三个人没听见。</p><p>戴耳机那个在剪指甲。</p><p>对面那两个人在讲明天去哪吃。</p><p>我说，什么意思。</p><p>陈树说，我不明白一件事。</p><p>他说，你要说你们谈恋爱，我不信。</p><p>他说，我从来没听你讲过一个人在你旁边。</p><p>他说，你要说你们没谈。</p><p>他说，那你这四年每天晚上九点到十一点，你雷打不动。</p><p>他说，我见过谈恋爱的，我没见过谈一场恋爱四年不伸手的。</p><p>他说，所以你俩这算什么。</p><p>我坐在那儿。</p><p>那二十分钟里片子在下雨。</p><p>我说，我不知道怎么说。</p><p>陈树说，我告诉你怎么说。</p><p>他说，你这是供着一个东西。</p><p>他说，你供的那个东西是不是活的我不管。</p><p>他说，你每天上香，你说今天这个香是我昨天剩下的，我给你换上。</p><p>他说，你四年了。</p><p>他说，你那块香都认得你了。</p><p>我说，你说够了没有。</p><p>陈树说不。</p><p>他说，我还没讲最要紧的。</p><p>他说，你知不知道你这个样子，最对不起的不是她。</p><p>我说，那是谁。</p><p>他说，是你自己以后要碰的那个人。</p><p>他说，你以后要是碰见一个真人，她会坐在你对面吃饭。</p><p>她说，你今天能不能别拿手机。</p><p>你说，我拿一下，就一下。</p><p>她说，你一下一下一天了。</p><p>他说，那个时候你怎么办。</p><p>他说，你说你跟她没什么，那你对面这个人就白坐。</p><p>他说，你说你有她，那你手里这个活人就废了。</p><p>他说，你现在这个状态，你两边都输。</p><p>我那天晚上没说话。</p><p>片子里那场雨下完了，开始有音乐。</p><p>陈树把遥控器拿回去。</p><p>他说，我不劝你分。</p><p>他说，我从来不劝人分。</p><p>他说，我说的是你这个人。</p><p>他说，你这一年你脸上就没松过。</p><p>他说，你在等一个不回你的人，你以为你在守。</p><p>他说，守是要有人回来的。</p><p>他说，你这是坐在那儿不动。</p><p>他说，不动跟守不是一件事。</p><p>那天夜里我们看完了那个片子。</p><p>十点四十散。</p><p>十一点我照旧上线。</p><p>她那边的下午五点四十，她刚下课。</p><p>她发的是：我今天那个批下来了。</p><p>她说，他们给我一块布。</p><p>她说，我把那个本子放进柜子最上面一层。</p><p>她说，我今天忽然觉得我这个人，我这一辈子所有东西都在往上挪。</p><p>她说，挪到别人够不着的地方，就安全了。</p><p>我说，那你那个猫呢。</p><p>她说，猫不用挪。</p><p>她说，猫是自己会跳上窗台的。</p><p>我说，那挺好。</p><p>她说，你又&quot;那挺好&quot;。</p><p>我说，我今天不想讲别的。</p><p>她说，你怎么了。</p><p>我说，我今天听人讲了一句话。</p><p>她说，谁讲。</p><p>我说，我室友。</p><p>她说，讲的什么。</p><p>我坐在那儿，看着这一行。</p><p>我那天晚上第一次差一点讲出来。</p><p>差一点我就打了那七个字：他问我我们算什么。</p><p>我要是打了，她就要回答。</p><p>她回答不了，她今天晚上就要开始算她这四年。</p><p>她一算，她就要开始讲她为什么回不了。</p><p>她讲完，她明天那张图就画不完。</p><p>我这四年做过太多次这件事了。</p><p>我把那七个字删了。</p><p>我发的是：没什么，他讲错了。</p><p>她说，他讲错了你还记到现在。</p><p>我说，我记东西快。</p><p>她说，你记东西快这个毛病，什么时候能改。</p><p>我说，改不了。</p><p>她说，你连这个都承认。</p><p>我说，我什么都认。</p><p>她说，你不认&quot;我们&quot;。</p><p>那天我们提前下线。</p><p>十一点二十一分，她说了一句晚安。</p><p>我说，晚安。</p><p>我关了屏幕。</p><p>我那天夜里没睡着。</p><p>我在算一件事。</p><p>陈树说，守是要有人回来的。</p><p>我这一辈子所有的力气，全放在&quot;我不催她回来&quot;上面。</p><p>我不催，是因为我一催，我就得听答案。</p><p>我那天夜里想：我到底是爱她，还是爱这个不用听答案的状态。</p><p>我算不出来。</p><p>我这辈子第一次算不出来一个东西，我居然没有难受。</p><p>因为如果我算得出来，我就必须做点什么。</p><p>我什么都没做。</p><p>我那天夜里只把那个箱子从床底下拖出来，看了一眼胶带。</p><p>胶带还是两道。</p><p>我推回去了。</p><p>那年十二月，我做了一件很小的事。</p><p>我这辈子唯一一次听陈树的话。</p><p>我们系里组织去看一个东西，二十几个人，坐一辆大巴。</p><p>我报名了。</p><p>我报名那天晚上跟她讲了。</p><p>我说，我下周跟系里出去一天。</p><p>她说，去哪儿。</p><p>我说，不远，一个工广。</p><p>她说，那你那天几点能上线。</p><p>我说，晚上。</p><p>她说，晚上你一般在车上。</p><p>我说，我在车上也能讲。</p><p>她隔了一会儿。</p><p>她说，那你去吧。</p><p>她说，你四年没出去过一次。</p><p>我说，我去了。</p><p>她说，我知道你去了。</p><p>她说，我就是想你有一天能自己讲一句你去。</p><p>那天我上车的时候，我把手机关了。</p><p>关了一整个白天。</p><p>我在车上睡着了两次。</p><p>我拍了一张照片，拍的是一排田，田后面有一个信号塔。</p><p>我那天晚上打开手机，有十四条。</p><p>前面三条是她下午五点发的。</p><p>后面十一条，是她那边夜里十一点到早上六点之间发的。</p><p>她夜里十一点发了六条。</p><p>她早上六点又发了五条。</p><p>中间那一条是：你今天怎么没在。</p><p>我看那十一条，坐在宿舍床沿上很久。</p><p>因为我那一天关机的十四个钟头里，她那边从下午五点一直到早上六点。</p><p>她这一天没有一个人接。</p><p>我那天晚上把那张拍田的照片发出去。</p><p>我说，今天在车上拍的。</p><p>她说，拍得真好。</p><p>她说，你下次多拍。</p><p>她说，我今天这一天讲话讲得很多，因为没有你，我只能打出来。</p><p>她说，我以前以为我打字少是因为我不爱讲。</p><p>她说，我今天发现我不讲是因为你总是一下就回。</p><p>她说，你今天不在，我才发现我有十一条要讲。</p><p>我那天晚上在本子上写了一行。</p><p>我写：我今天关机十四个钟头，换来她说她本来有十一条。</p><p>我写：那我要是每次都晚回十四个钟头，我是不是就能多拿十一条。</p><p>我写：我没打算这么做。</p><p>我写：但是我今天确实看见了，我早回，是在替她把话说完。</p>',172)])])}const q=t(_,[["render",r]]);export{l as __pageData,q as default};
